v = input().split()
n = int(v[0])
p = int(v[1])
c = list(map(int, input().split()))
def sp(kd):
    f = [0] * p
    if kd == "static":
        q, r = divmod(n, p)
        s = 0
        for t in range(p):
            z = q + (t < r)
            f[t] = sum(c[s:s + z])
            s += z
    elif kd == "cyclic":
        for i in range(n):
            f[i % p] += c[i]
    else:
        s = 0
        while s < n:
            z = 1 if kd == "dynamic" else max(1, -(-(n - s) // p))
            e = min(n, s + z)
            t = f.index(min(f))
            f[t] += sum(c[s:e])
            s = e
    return max(f)
best = None
for kd in ["static","cyclic","dynamic","guided"]:
    if best is None or sp(kd) < sp(best):
        best = kd
print(best)

